// Exercise xt::argument<I>(Args&&...) by selecting among fixed I values at compile time.
// Constraints: I < sizeof...(Args). We instantiate three legal I values and dispatch via a runtime index.
int v0 = static_cast<int>(*FUZZ_PARAM(unsigned int) % 1000);
double v1 = static_cast<double>(*FUZZ_PARAM(unsigned int) % 1000) / 7.0;
std::string v2 = FUZZ_PARAM_STR();
// Choose which instantiation to call; bound index to [0,2].
std::size_t idx = *FUZZ_PARAM(unsigned int) % 3;
switch (idx) {
    case 0: {
        // Perfect-forwarding: pass lvalues/rvalues mixture.
        auto&& r = xt::argument<0>(v0, v1, v2);
        // Property: returned reference/value corresponds to the selected argument.
        FUZZ_ASSERT(&r == &v0, "xt::argument<0> must return the first argument");
        break;
    }
    case 1: {
        auto&& r = xt::argument<1>(v0, std::move(v1), v2);
        // Can't compare address reliably for moved-from rvalues; assert by value equality.
        FUZZ_ASSERT(static_cast<double>(r) == v1, "xt::argument<1> must yield the second argument");
        break;
    }
    default: {
        auto&& r = xt::argument<2>(v0, v1, std::move(v2));
        FUZZ_ASSERT(r.size() == v2.size(), "xt::argument<2> must yield the third argument");
        break;
    }
}
// Validation: We instantiate only valid I values and assert returned selection matches expectation.

// Build a heterogeneous tuple and apply a lambda to the element at a runtime index.
