    static_cast<int>(*FUZZ_PARAM(unsigned int) % 1000),
    static_cast<double>(*FUZZ_PARAM(unsigned int) % 1000) / 3.0,
    FUZZ_PARAM_STR()
);
// The callable returns a size_t for any of the alternatives.
auto func = [](const auto& x) -> std::size_t {
    using X = std::decay_t<decltype(x)>;
    if constexpr (std::is_same<X, int>::value) {
        return static_cast<std::size_t>(x < 0 ? -x : x);
    } else if constexpr (std::is_same<X, double>::value) {
        return static_cast<std::size_t>(x >= 0.0 ? x : -x);
    } else {
        return x.size();
    }
};
// Enforce index bounds [0,3).
